(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  var EXPLAIN = {"complex-transform":{"h":"WHAT YOU ARE LOOKING AT","t":"Apply **A** to the blue square. It becomes the pink slanted shape: **stretched and sheared** in a hard-to-read way."},"eigen-directions":{"h":"FIND ITS SPECIAL DIRECTIONS","t":"A has two **eigen-directions**, **[1, 1] and [1, −1]**. They are the natural axes of this transformation."},"change-basis":{"h":"CHANGE COORDINATES TO THOSE DIRECTIONS","t":"Rotate the view so the eigen-directions line up with the screen axes. This is the **P⁻¹ step**: we look at the same problem from a better angle."},"diagonal-space":{"h":"HERE A ONLY STRETCHES EACH AXIS","t":"In these coordinates A does something simple: it **stretches the first axis by 3 and the second by 1**. That is a **diagonal matrix D**."},"scale":{"h":"SCALE EACH AXIS INDEPENDENTLY","t":"Apply D: stretch by 3 along the first axis and leave the second alone. The axes **do not affect each other**."},"change-back":{"h":"CHANGE BACK TO THE ORIGINAL COORDINATES","t":"Rotate back (the **P step**). The result is exactly the slanted shape that A produced directly in the first step."},"decomposition":{"h":"TAKEAWAY","t":"**A = P D P⁻¹.** Change coordinates, scale each axis, change back: a hard transformation becomes **three simple moves**."}};
  // ── scene ──
  var steps = [
    { id: "complex-transform", label: "A transformation that looks complicated", caption: "Apply A to the blue square. It becomes the pink slanted shape: stretched and sheared in a hard-to-read way." },
    { id: "eigen-directions", label: "Find its special directions", caption: "A has two eigen-directions, [1, 1] and [1, −1]. They are the natural axes of this transformation." },
    { id: "change-basis", label: "Change coordinates to those directions", caption: "Rotate the view so the eigen-directions line up with the screen axes. This is the P⁻¹ step." },
    { id: "diagonal-space", label: "Here A only stretches each axis", caption: "In these coordinates A does something simple: it stretches the first axis by 3 and the second by 1. That is a diagonal matrix D." },
    { id: "scale", label: "Scale each axis independently", caption: "Apply D: stretch by 3 along the first axis and leave the second alone. The axes do not affect each other." },
    { id: "change-back", label: "Change back to the original coordinates", caption: "Rotate back (the P step). The result is exactly the pink shape that A produced directly." },
    { id: "decomposition", label: "A = P D P⁻¹", caption: "Change coordinates, scale each axis, change back. A hard transformation becomes three simple moves." }
  ];

  var P = makePlane(200, 190, 38);
  var K = 1.2;
  var S = [[0, 0], [K, 0], [K, K], [0, K]];
  var Am = [[2, 1], [1, 2]];
  var AS = S.map(function (p) { return [Am[0][0] * p[0] + Am[0][1] * p[1], Am[1][0] * p[0] + Am[1][1] * p[1]]; });
  var C45 = Math.cos(Math.PI / 4);

  function rot(p, deg) {
    var r = (deg * Math.PI) / 180;
    return [p[0] * Math.cos(r) - p[1] * Math.sin(r), p[0] * Math.sin(r) + p[1] * Math.cos(r)];
  }
  // change basis (rotate by -45° · a), scale (sx, 1), change back (rotate by +45° · b)
  var st = { a: 0, b: 0, sx: 1 };
  function xf(p) {
    var q = rot(p, -45 * st.a);
    q = [q[0] * st.sx, q[1]];
    return rot(q, 45 * st.b);
  }
  // Axis lines and tags follow the rotations but are NOT stretched.
  function xfAxis(p) {
    return rot(rot(p, -45 * st.a), 45 * st.b);
  }

  axes(svg, P, 5, 4.9);
  var ghost = polygon(svg, "fillB");
  setPoly(ghost, AS.map(P.pt));
  var ghostLab = txt(svg, P.x(AS[2][0]) + 8, P.y(AS[2][1]) - 6, "lbl lbl-p", "A applied directly", "start");
  var shape = polygon(svg, "fillA");
  var lineA = el("line", { stroke: "#e2b44a", "stroke-width": 2, class: "dash" }, svg);
  var lineB = el("line", { stroke: "#f472b6", "stroke-width": 2, class: "dash" }, svg);
  var tagX = txt(svg, 0, 0, "lbl lbl-y", "", "start");
  var tagY = txt(svg, 0, 0, "lbl lbl-p", "", "start");

  function draw() {
    setPoly(shape, S.map(function (p) { return P.pt(xf(p)); }));
    var a1 = P.pt(xfAxis([-4.2, -4.2])), a2 = P.pt(xfAxis([4.2, 4.2]));
    var b1 = P.pt(xfAxis([-3.2, 3.2])), b2 = P.pt(xfAxis([3.2, -3.2]));
    setLine(lineA, a1[0], a1[1], a2[0], a2[1]);
    setLine(lineB, b1[0], b1[1], b2[0], b2[1]);
    var ta = P.pt(xfAxis([3.4, 3.4]));
    var tb = P.pt(xfAxis([-2.2, 2.2]));
    tagX.setAttribute("x", ta[0] + 6); tagX.setAttribute("y", ta[1] - 4);
    tagY.setAttribute("x", tb[0] + 6); tagY.setAttribute("y", tb[1] - 4);
  }
  draw();

  // Decomposition panel.
  var panel = el("g", { opacity: 0 }, svg);
  var rows = [["1", "change coordinates", "P⁻¹"], ["2", "scale each axis", "D"], ["3", "change back", "P"]];
  rows.forEach(function (r, i) {
    el("rect", { x: 420, y: 64 + i * 78, width: 204, height: 56, rx: 12, class: "fillG" }, panel);
    txt(panel, 436, 88 + i * 78, "lbl", r[0] + "  " + r[1], "start");
    txt(panel, 436, 108 + i * 78, "mono", r[2], "start");
    if (i < 2) el("line", { x1: 522, y1: 122 + i * 78, x2: 522, y2: 140 + i * 78, stroke: "#a7ce65", "stroke-width": 2.5, "marker-end": "url(#ah-g)" }, panel);
  });
  var formula = txt(svg, 520, 322, "big", "A = P D P⁻¹", "middle");
  show(formula, false);

  function goState(target, ms) {
    var from = { a: st.a, b: st.b, sx: st.sx };
    anim("diag", ms, function (e) {
      st.a = lerp(from.a, target.a, e);
      st.b = lerp(from.b, target.b, e);
      st.sx = lerp(from.sx, target.sx, e);
      draw();
    });
  }

  function render(index, id) {
    show(ghost, id === "complex-transform" || id === "change-back" || id === "decomposition");
    show(ghostLab, id === "change-back" || id === "complex-transform");
    show(lineA, index >= 1); show(lineB, index >= 1);
    show(panel, id === "decomposition");
    show(formula, id === "decomposition");
    tagX.textContent = ""; tagY.textContent = "";

    if (id === "complex-transform") goState({ a: 0, b: 0, sx: 1 }, 300);
    else if (id === "eigen-directions") goState({ a: 0, b: 0, sx: 1 }, 300);
    else if (id === "change-basis") goState({ a: 1, b: 0, sx: 1 }, 1100);
    else if (id === "diagonal-space") {
      goState({ a: 1, b: 0, sx: 1 }, 200);
      tagX.textContent = "×3";
      tagY.textContent = "×1";
    } else if (id === "scale") {
      goState({ a: 1, b: 0, sx: 3 }, 1100);
      tagX.textContent = "×3";
      tagY.textContent = "×1";
    } else if (id === "change-back") goState({ a: 1, b: 1, sx: 3 }, 1100);
    else goState({ a: 1, b: 1, sx: 3 }, 200);
  }


  // ── shared runtime: stepping, explanation panel, educational autoplay pacing, bridge ──
  var current = 0;
  var explainHeadEl = document.getElementById("explain-h");

  // **bold** markers in an explanation become <strong> nodes (built with DOM calls, never innerHTML).
  function setRich(node, str) {
    node.textContent = "";
    var parts = String(str).split("**");
    for (var i = 0; i < parts.length; i++) {
      if (parts[i] === "") continue;
      var seg = document.createElement(i % 2 ? "strong" : "span");
      seg.textContent = parts[i];
      node.appendChild(seg);
    }
  }

  function explanationFor(index) {
    var ex = (typeof EXPLAIN === "object" && EXPLAIN) ? EXPLAIN[steps[index].id] : null;
    return ex || { h: "WHAT IS HAPPENING", t: steps[index].caption };
  }

  // Autoplay pace: 4.5 to 10.5 seconds per step, longer for longer explanations, so a learner can read.
  function stepMs(index) {
    var words = String(explanationFor(index).t).replace(/\*\*/g, "").split(/\s+/).length;
    return Math.max(4500, Math.min(10500, Math.round(3800 + words * 165)));
  }

  function renderStep(index) {
    var ex = explanationFor(index);
    labelEl.textContent = steps[index].label;
    if (explainHeadEl) explainHeadEl.textContent = ex.h;
    setRich(captionEl, ex.t);
    render(index, steps[index].id);
  }

  function goTo(index) {
    if (index < 0 || index >= steps.length) return;
    current = index;
    renderStep(current);
    if (window.ReagvisBridge) window.ReagvisBridge.stepChanged(steps[current].id);
  }

  renderStep(current);

  // Autoplay: exactly one timer, one step per tick, stops on the final step.
  // PLAY on the final step restarts from the first step and plays again.
  var timer = null;

  function stopAuto() {
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }
  }

  function scheduleNext() {
    timer = setTimeout(function () {
      timer = null;
      if (current >= steps.length - 1) return;
      goTo(current + 1);
      if (current < steps.length - 1) scheduleNext();
    }, stepMs(current));
  }

  function startAuto() {
    if (timer !== null) return;
    if (current >= steps.length - 1) goTo(0);
    scheduleNext();
  }

  window.addEventListener("pagehide", stopAuto);

  window.ReagvisAnimation = {
    stepDuration: stepMs,
    onCommand: function (type, stepId) {
      if (type === "PLAY") startAuto();
      else if (type === "PAUSE") stopAuto();
      else if (type === "NEXT") { stopAuto(); goTo(current + 1); }
      else if (type === "PREVIOUS") { stopAuto(); goTo(current - 1); }
      else if (type === "RESET") { stopAuto(); goTo(0); }
      else if (type === "GOTO_STEP") {
        stopAuto();
        for (var i = 0; i < steps.length; i++) {
          if (steps[i].id === stepId) { goTo(i); break; }
        }
      }
    },
  };

  if (window.ReagvisBridge) {
    window.ReagvisBridge.ready();
    window.ReagvisBridge.stepChanged(steps[current].id);
  }
})();
